package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time email handling for {@code POST /owners}. Email is optional: an absent (null or
 * blank) value is left untouched and the request proceeds. When a value is supplied it must be
 * a syntactically valid address — otherwise the request is rejected with 400 via
 * {@link InvalidEmailException}. A valid value is normalised (trimmed and lower-cased) and
 * written back onto the body in place (the {@code @Val} object is the same instance
 * {@link BuildOwner} then maps), so the lower-cased form is what gets stored and returned.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and before {@link CheckOwnerTelephoneUnique}.
 */
public class NormalizeOwnerEmail {

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (!OwnerEmail.isPresent(email)) {
            return;
        }
        if (!OwnerEmail.isValid(email)) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(OwnerEmail.normalize(email));
    }
}
===== CheckOwnerHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time household guard for {@code POST /owners}: rejects a request whose last name and
 * address both match an existing owner's, with a 409 via {@link DuplicateHouseholdException}.
 *
 * <p>Last name and address are compared case-insensitively with collapsed whitespace, so values
 * that differ only in letter case or spacing count as the same household. A request may opt out
 * of the check by setting {@code sharesHousehold} true (several owners legitimately share one
 * household), in which case the duplicate is allowed.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.matches(request, existing)) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Household assignment for {@code POST /owners}. When the request opts in via
 * {@code sharesHousehold} true, the new owner joins the household of any existing owner it
 * {@link OwnerHousehold#matches matches}. Both the joining owner and the matched existing
 * owners are assigned the same {@code householdId} — a stable shared identifier (see
 * {@link OwnerHousehold#deriveId}) — so the household is discoverable from any of its members.
 * If a matched owner already carries a {@code householdId}, that value is reused so the
 * identifier stays stable as further members join.
 *
 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignCustomerCode},
 * before {@link SaveOwner}) so the back-filled identifiers on existing owners commit with the
 * new owner. Requests without {@code sharesHousehold} leave {@code householdId} null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        List<Owner> matches = new ArrayList<>();
        String householdId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.matches(request, existing)) {
                matches.add(existing);
                if (householdId == null && existing.getHouseholdId() != null) {
                    householdId = existing.getHouseholdId();
                }
            }
        }
        if (householdId == null) {
            householdId = OwnerHousehold.deriveId(request);
        }
        owner.setHouseholdId(householdId);
        for (Owner existing : matches) {
            if (!householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }
}
